import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import './Homepage.css';

function Homepage() {
    const [input, setInput] = useState('');
    const [result, setResult] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    const handleCheck = async () => {
        if (!input.trim()) {
            setError('Please enter some content to verify');
            return;
        }

        setLoading(true);
        setError(null);

        try {
            const response = await axios.post('http://localhost:5001/api/check', { 
                content: input 
            });

            if (response.data.error) {
                throw new Error(response.data.error);
            }

            setResult(response.data);
        } catch (error) {
            console.error('Error Details:', error);
            const errorMessage = error.response?.data?.details || 
                               error.response?.data?.error || 
                               error.message || 
                               'Failed to analyze content';
            setError(errorMessage);
            setResult(null);
        } finally {
            setLoading(false);
        }
    };

    const renderResult = () => {
        if (!result) return null;

        const { summary, analysis } = result;

        // Calculate confidence levels for each category
        const analysisResults = analysis.labels.map((label, index) => ({
            label: label.charAt(0).toUpperCase() + label.slice(1), // Capitalize first letter
            confidence: Math.round(analysis.scores[index] * 100),
            color: analysis.scores[index] > 0.5 ? '#28a745' : '#dc3545'
        }));

        // Sort by confidence
        analysisResults.sort((a, b) => b.confidence - a.confidence);

        return (
            <div className="result">
                <h3>Content Analysis Result</h3>

                {/* Add color legend */}
                <div className="color-legend">
                    <div className="legend-item">
                        <span className="legend-color" style={{ backgroundColor: '#28a745' }}></span>
                        <span className="legend-text">High Confidence (>50%)</span>
                    </div>
                    <div className="legend-item">
                        <span className="legend-color" style={{ backgroundColor: '#dc3545' }}></span>
                        <span className="legend-text">Low Confidence (≤50%)</span>
                    </div>
                </div>

                <div className="result-summary">
                    <div className="result-item primary">
                        <span>Primary Classification</span>
                        <strong style={{ color: analysisResults[0].color }}>
                            {analysisResults[0].label}
                        </strong>
                        <div className="confidence-bar">
                            <div 
                                className="confidence-fill" 
                                style={{ 
                                    width: `${analysisResults[0].confidence}%`,
                                    backgroundColor: analysisResults[0].color 
                                }}
                            />
                        </div>
                        <span className="confidence-text">
                            {analysisResults[0].confidence}% Confidence
                        </span>
                    </div>
                </div>

                <div className="detailed-results">
                    <h4>Detailed Breakdown:</h4>
                    <div className="analysis-breakdown">
                        {analysisResults.map((item, index) => (
                            <div key={index} className="breakdown-item">
                                <div className="breakdown-label">{item.label}</div>
                                <div className="breakdown-bar-container">
                                    <div 
                                        className="breakdown-bar" 
                                        style={{ 
                                            width: `${item.confidence}%`,
                                            backgroundColor: item.color
                                        }}
                                    />
                                    <span className="breakdown-percentage">
                                        {item.confidence}%
                                    </span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="homepage">
            <header className="header">
                <h1>TruthGuard</h1>
                <p>Your trusted content verification platform</p>
            </header>

            <main className="content-checker">
                <div className="input-section">
                    <textarea
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        placeholder="Enter content to verify..."
                        rows="6"
                        disabled={loading}
                    />
                    {error && <div className="error-message">{error}</div>}
                    <button 
                        onClick={handleCheck} 
                        disabled={loading || !input.trim()}
                        className={loading ? 'loading' : ''}
                    >
                        {loading ? 'Analyzing...' : 'Verify Content'}
                    </button>
                </div>

                {renderResult()}
            </main>

            <footer className="footer">
                <Link to="/dashboard" className="dashboard-link">
                    View Analysis History
                </Link>
            </footer>
        </div>
    );
}

export default Homepage;
